class Ledger:
    def __init__(self, connection):
        self.connection = connection

    def open_entries(self):
        rows = self.connection.execute("SELECT id, kind, due_on FROM expenses WHERE status = 'draft'")
        return [{"id": key, "kind": kind, "due_on": day} for key, kind, day in rows]

    def close(self, key, reason):
        with self.connection:
            self.connection.execute(
                "UPDATE expenses SET status = 'closed', reason = ? WHERE id = ? AND status = 'draft'",
                (reason, key),
            )

