from datetime import datetime, timedelta

SHIFT_END = {"RS": 3, "HT": 1}


def trading_date(entry):
    local = datetime.fromisoformat(entry["booked_at"])
    if local.hour < SHIFT_END[entry["site"]]:
        local -= timedelta(days=1)
    return local.date().isoformat()

